#!/usr/bin/env python3
"""Audit of THM-4665, Open section: the group generated by the mirror M, the graph automorphism A (re-gauged) and the
block re-placement iota on the gauge-fixed faithful solutions: commutation, orbit sizes, stabilisers.
"""
import os
os.environ.setdefault('NUMBA_CACHE_DIR', os.path.join(os.environ.get('TEMP', os.environ.get('TMPDIR', '/tmp')), 'nbc_s39_audit_ei17'))  # short path outside the repo (Windows MAX_PATH)
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import a2_embedding_search as A2  # noqa: E402
import a6_verify_embeddings as A6  # noqa: E402

ST, _ = A2.pick_order(); ARR = A2.order_arrays(ST)


def ops(model, p, b):
    F = A6.Fq2(p, b)
    if model == 0:
        inv = lambda z: (pow(z[0], -1, p), pow(z[1], -1, p))
        mul = lambda x, y: ((x[0] * y[0]) % p, (x[1] * y[1]) % p)
        conj = lambda z: (z[1], z[0])
        one = (1, 1); mone = (p - 1, p - 1)
    else:
        inv = lambda z: F.pow(z, p * p - 2)
        mul = F.mul
        conj = lambda z: ((z[0] + z[1]) % p, (-z[1]) % p)
        one = (1, 0); mone = (p - 1, 0)
    add = lambda x, y: ((x[0] + y[0]) % p, (x[1] + y[1]) % p)
    sub = lambda x, y: ((x[0] - y[0]) % p, (x[1] - y[1]) % p)

    def M(T):
        return tuple(conj(z) for z in T)

    def A(T):
        P = {v: T[v - 1] for v in range(1, 18)}
        r = mul(mone, inv(P[14]))
        return tuple(mul(r, P[A6.AUT[v]]) for v in range(1, 18))

    def I(T):
        P = {v: T[v - 1] for v in range(1, 18)}
        Q = dict(P)
        for v in (4, 6):
            Q[v] = sub(add(P[1], P[14]), P[v])
        Q[13] = add(Q[4], sub(P[17], P[14]))
        Q[16] = add(Q[6], one)
        return tuple(Q[v] for v in range(1, 18))
    return M, A, I


for model, plist in ((0, (103, 139, 281, 313, 401, 499, 521, 541, 631, 641, 677, 2861, 3191)),
                     (1, (127, 149, 227, 277, 283, 311, 317, 349, 383, 397, 443, 463, 547, 587, 2441, 2551))):
    for p in plist:
        b, sols = A2.solutions(model, p, ARR)
        S = {tuple(tuple(int(c) for c in s[v - 1]) for v in range(1, 18)) for s in sols}
        M, A, I = ops(model, p, b)
        comm = all(M(A(T)) == A(M(T)) and M(I(T)) == I(M(T)) and A(I(T)) == I(A(T)) for T in S)
        invol = all(M(M(T)) == T and A(A(T)) == T and I(I(T)) == T for T in S)
        closed = all(M(T) in S and A(T) in S and I(T) in S for T in S)
        orbits, seen, stabs = [], set(), set()
        G = {'1': lambda T: T, 'M': M, 'A': A, 'I': I, 'MA': lambda T: M(A(T)), 'MI': lambda T: M(I(T)),
             'AI': lambda T: A(I(T)), 'MAI': lambda T: M(A(I(T)))}
        for T in S:
            if T in seen:
                continue
            orb = {g(T) for g in G.values()}
            seen |= orb; orbits.append(len(orb))
            stabs |= {k for k, g in G.items() if k != '1' and g(T) == T}
        print('%s p = %5d: %2d solutions; M, A, iota involutions %s, commute %s, preserve the set %s; orbit sizes %s; '
              'non-identity elements with fixed points: %s'
              % ('split  ' if model == 0 else 'twisted', p, len(S), invol, comm, closed, sorted(orbits), sorted(stabs) or 'none'))
